//! The frozen forge state and its lookups.
//!
//! This module is CLI-free: no clap, no standout, no rendering. It owns the
//! data and the "does this exist?" questions; the shell layer adapts it.

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Visibility {
    Public,
    Private,
}

impl Visibility {
    pub fn as_str(self) -> &'static str {
        match self {
            Visibility::Public => "public",
            Visibility::Private => "private",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum PrState {
    Open,
    Merged,
}

impl PrState {
    pub fn as_str(self) -> &'static str {
        match self {
            PrState::Open => "open",
            PrState::Merged => "merged",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CheckStatus {
    Pass,
    Fail,
}

impl CheckStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            CheckStatus::Pass => "pass",
            CheckStatus::Fail => "fail",
        }
    }
}

#[derive(Clone, Copy)]
pub struct Repo {
    pub name_with_owner: &'static str,
    pub description: &'static str,
    pub visibility: Visibility,
}

#[derive(Clone, Copy)]
pub struct PullRequest {
    pub number: u32,
    pub title: &'static str,
    pub state: PrState,
    pub author: &'static str,
    pub draft: bool,
}

#[derive(Clone, Copy)]
pub struct Check {
    pub name: &'static str,
    pub status: CheckStatus,
}

const REPOS: &[Repo] = &[
    Repo {
        name_with_owner: "demo/alpha",
        description: "Alpha service",
        visibility: Visibility::Public,
    },
    Repo {
        name_with_owner: "demo/beta",
        description: "Beta tools",
        visibility: Visibility::Private,
    },
];

const PULL_REQUESTS: &[PullRequest] = &[
    PullRequest {
        number: 1,
        title: "Add pager",
        state: PrState::Open,
        author: "alice",
        draft: false,
    },
    PullRequest {
        number: 2,
        title: "Fix theme",
        state: PrState::Merged,
        author: "bob",
        draft: false,
    },
    PullRequest {
        number: 3,
        title: "Docs pass",
        state: PrState::Open,
        author: "alice",
        draft: true,
    },
];

/// The authenticated user of the frozen state.
pub fn login() -> &'static str {
    "corpus-bot"
}

pub fn find_repo(name_with_owner: &str) -> Option<Repo> {
    REPOS
        .iter()
        .copied()
        .find(|repo| repo.name_with_owner == name_with_owner)
}

pub fn pull_requests() -> Vec<PullRequest> {
    PULL_REQUESTS.to_vec()
}

/// Pull requests are addressed by the number as the user typed it, so an
/// unusable value is "not found" rather than a parse failure.
pub fn find_pull_request(number: &str) -> Option<PullRequest> {
    PULL_REQUESTS
        .iter()
        .copied()
        .find(|pr| pr.number.to_string() == number)
}

pub fn checks_for(pr: &PullRequest) -> Vec<Check> {
    match pr.number {
        1 => vec![
            Check {
                name: "build",
                status: CheckStatus::Pass,
            },
            Check {
                name: "lint",
                status: CheckStatus::Pass,
            },
        ],
        2 => vec![
            Check {
                name: "build",
                status: CheckStatus::Pass,
            },
            Check {
                name: "lint",
                status: CheckStatus::Pass,
            },
        ],
        _ => Vec::new(),
    }
}
