//! `--json <fields>`: field selection for the machine-facing output.
//!
//! The selected fields are emitted in the order the caller asked for them, as
//! compact JSON, so the bytes on stdout stay predictable for scripts.

use serde_json::Value;

use crate::forge::{Check, PullRequest};

pub const PR_FIELDS: &[&str] = &["number", "title", "state", "author", "draft"];
pub const CHECK_FIELDS: &[&str] = &["name", "status"];

/// Parse a comma-separated field list, rejecting anything not in `available`.
pub fn parse_fields(spec: &str, available: &[&str]) -> Result<Vec<String>, String> {
    let mut fields: Vec<String> = Vec::new();
    for raw in spec.split(',') {
        let field = raw.trim();
        if !available.contains(&field) {
            return Err(format!(
                "ghlike: unknown JSON field: {} (available fields: {})\n",
                field,
                available.join(", ")
            ));
        }
        if !fields.iter().any(|kept| kept == field) {
            fields.push(field.to_string());
        }
    }
    Ok(fields)
}

fn pr_value(pr: &PullRequest, field: &str) -> Value {
    match field {
        "number" => Value::from(pr.number),
        "title" => Value::from(pr.title),
        "state" => Value::from(pr.state.as_str()),
        "author" => Value::from(pr.author),
        "draft" => Value::from(pr.draft),
        _ => Value::Null,
    }
}

fn check_value(check: &Check, field: &str) -> Value {
    match field {
        "name" => Value::from(check.name),
        "status" => Value::from(check.status.as_str()),
        _ => Value::Null,
    }
}

fn object(fields: &[String], value_of: impl Fn(&str) -> Value) -> String {
    let body: Vec<String> = fields
        .iter()
        .map(|field| format!("{}:{}", Value::from(field.as_str()), value_of(field)))
        .collect();
    format!("{{{}}}", body.join(","))
}

fn array(objects: Vec<String>) -> String {
    format!("[{}]", objects.join(","))
}

/// A single pull request as a JSON object, newline-terminated.
pub fn pull_request(pr: &PullRequest, fields: &[String]) -> Vec<u8> {
    document(object(fields, |field| pr_value(pr, field)))
}

/// Pull requests as a JSON array, newline-terminated.
pub fn pull_requests(prs: &[PullRequest], fields: &[String]) -> Vec<u8> {
    document(array(
        prs.iter()
            .map(|pr| object(fields, |field| pr_value(pr, field)))
            .collect(),
    ))
}

/// Checks as a JSON array, newline-terminated.
pub fn checks(checks: &[Check], fields: &[String]) -> Vec<u8> {
    document(array(
        checks
            .iter()
            .map(|check| object(fields, |field| check_value(check, field)))
            .collect(),
    ))
}

fn document(json: String) -> Vec<u8> {
    format!("{}\n", json).into_bytes()
}
