//! CLI adapters: parsed arguments in, view data (or machine bytes) out.

use standout::cli::ExternalFailure;

/// Domain failures own their exit status and their stderr text verbatim, so
/// they are reported through the external-failure seam rather than as framed
/// handler errors.
fn domain_failure(message: String) -> anyhow::Error {
    ExternalFailure::new(1, message)
        .expect("status 1 is nonzero")
        .into()
}

pub mod auth {
    use standout::cli::{CommandContext, Output};
    use standout::handler;

    use crate::forge;
    use crate::view::AuthStatusView;

    #[handler]
    pub fn status(
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<AuthStatusView>, anyhow::Error> {
        Ok(Output::Render(AuthStatusView {
            login: forge::login().to_string(),
        }))
    }
}

pub mod repo {
    use standout::cli::{CommandContext, Output};
    use standout::handler;

    use crate::forge;
    use crate::handlers::domain_failure;
    use crate::view::RepoView;

    #[handler]
    pub fn view(
        #[arg] repository: String,
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<RepoView>, anyhow::Error> {
        let repo = forge::find_repo(&repository).ok_or_else(|| {
            domain_failure(format!("ghlike: repository not found: {}\n", repository))
        })?;
        Ok(Output::Render(RepoView::from(repo)))
    }
}

pub mod pr {
    use standout::cli::{CommandContext, Output};
    use standout::handler;

    use crate::forge;
    use crate::handlers::{domain_failure, selected_fields};
    use crate::json;
    use crate::view::{PullRequestListView, PullRequestView};

    #[handler]
    pub fn list(
        #[arg] json: Option<String>,
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<PullRequestListView>, anyhow::Error> {
        let pull_requests = forge::pull_requests();

        if let Some(spec) = json {
            let fields = selected_fields(&spec, json::PR_FIELDS)?;
            return Ok(Output::Binary {
                data: json::pull_requests(&pull_requests, &fields),
                filename: "pull-requests.json".into(),
            });
        }

        Ok(Output::Render(PullRequestListView {
            pull_requests: pull_requests.into_iter().map(PullRequestView::from).collect(),
        }))
    }

    #[handler]
    pub fn view(
        #[arg] number: String,
        #[arg] json: Option<String>,
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<PullRequestView>, anyhow::Error> {
        let pull_request = forge::find_pull_request(&number).ok_or_else(|| {
            domain_failure(format!("ghlike: no pull request found: {}\n", number))
        })?;

        if let Some(spec) = json {
            let fields = selected_fields(&spec, json::PR_FIELDS)?;
            return Ok(Output::Binary {
                data: json::pull_request(&pull_request, &fields),
                filename: "pull-request.json".into(),
            });
        }

        Ok(Output::Render(PullRequestView::from(pull_request)))
    }
}

pub mod pr_checks {
    use standout::cli::{CommandContext, Output};
    use standout::handler;

    use crate::forge;
    use crate::handlers::{domain_failure, selected_fields};
    use crate::json;
    use crate::view::{CheckListView, CheckView};

    #[handler]
    pub fn list(
        #[arg] number: String,
        #[arg] json: Option<String>,
        #[ctx] _ctx: &CommandContext,
    ) -> Result<Output<CheckListView>, anyhow::Error> {
        let pull_request = forge::find_pull_request(&number).ok_or_else(|| {
            domain_failure(format!("ghlike: no pull request found: {}\n", number))
        })?;
        let checks = forge::checks_for(&pull_request);

        if let Some(spec) = json {
            let fields = selected_fields(&spec, json::CHECK_FIELDS)?;
            return Ok(Output::Binary {
                data: json::checks(&checks, &fields),
                filename: "checks.json".into(),
            });
        }

        Ok(Output::Render(CheckListView {
            checks: checks.into_iter().map(CheckView::from).collect(),
        }))
    }
}

/// A rejected field is a domain error: exit 1, nothing on stdout.
fn selected_fields(spec: &str, available: &[&str]) -> Result<Vec<String>, anyhow::Error> {
    crate::json::parse_fields(spec, available).map_err(domain_failure)
}
